const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const session_id = Number(input.session_id);
const message_id = Number(input.message_id);
const mobile = text(input.mobile);
const urgency = text(input.urgency || 'normal').toLowerCase();
const reason = text(input.reason);
const patient_message = text(input.patient_message);
const confirm_handoff = toBoolean(input.confirm_handoff);

let riskFlags = input.risk_flags ?? [];
if (typeof riskFlags === 'string') {
  try {
    riskFlags = JSON.parse(riskFlags || '[]');
  } catch {
    riskFlags = null;
  }
}

const allowedUrgencies = [
  'low',
  'normal',
  'high',
  'urgent',
];

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!Number.isInteger(session_id) || session_id < 1) {
  errors.push({
    field: 'session_id',
    message: 'session_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (!Number.isInteger(message_id) || message_id < 1) {
  errors.push({
    field: 'message_id',
    message: 'message_id باید یک عدد صحیح بزرگ‌تر از صفر باشد.',
  });
}

if (mobile && !/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل معتبر نیست.',
  });
}

if (!allowedUrgencies.includes(urgency)) {
  errors.push({
    field: 'urgency',
    message: 'اولویت ارجاع معتبر نیست.',
  });
}

if (!reason) {
  errors.push({
    field: 'reason',
    message: 'علت ارجاع انسانی الزامی است.',
  });
}

if (reason.length > 4000) {
  errors.push({
    field: 'reason',
    message: 'علت ارجاع بیش از حد طولانی است.',
  });
}

if (
  riskFlags === null ||
  !Array.isArray(riskFlags)
) {
  errors.push({
    field: 'risk_flags',
    message: 'risk_flags باید یک آرایه JSON معتبر باشد.',
  });
}

if (confirm_handoff !== true) {
  errors.push({
    field: 'confirm_handoff',
    message: 'ارجاع انسانی باید به‌صورت صریح تأیید شود.',
  });
}

return [{
  json: {
    clinic_name,
    session_id,
    message_id,
    mobile,
    urgency,
    reason,
    patient_message,
    risk_flags: riskFlags || [],
    risk_flags_json: JSON.stringify(riskFlags || []),
    confirm_handoff,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'اطلاعات ارجاع انسانی ناقص یا نامعتبر است.',
    errors: $json.errors ?? [],
  },
}];
